import { uniqueStrings } from './unique_changed.mjs';

// Basic dedup with case differences
const input = ['Apple', 'apple', 'BANANA', 'banana', 'Apple', 'cherry'];
const out = uniqueStrings(input);
console.log('out:', JSON.stringify(out));
console.assert(JSON.stringify(out) === JSON.stringify(['Apple', 'BANANA', 'cherry']), 'case dedup failed');

// Input not mutated
console.assert(JSON.stringify(input) === JSON.stringify(['Apple', 'apple', 'BANANA', 'banana', 'Apple', 'cherry']), 'input mutated');

// Whitespace preserved, not trimmed
const ws = ['  hi', 'hi', 'hi  ', '  hi'];
const wsOut = uniqueStrings(ws);
console.log('wsOut:', JSON.stringify(wsOut));
console.assert(JSON.stringify(wsOut) === JSON.stringify(['  hi', 'hi', 'hi  ']), 'whitespace handling failed');

// Empty array
console.assert(JSON.stringify(uniqueStrings([])) === '[]', 'empty failed');

// Original order retained
const order = ['b', 'A', 'a', 'B', 'c'];
console.assert(JSON.stringify(uniqueStrings(order)) === JSON.stringify(['b', 'A', 'c']), 'order failed');

console.log('All checks passed.');
"

